// Verify that `linear_search` either returns a valid index i
// such that nums[i] == target and that's the first such occurrence,
// or returns –1 to indicate no match.
#[verifier::pure]
#[requires(nums.len() < i32::MAX as usize)]
#[ensures(
    // If we return a non‐negative index, it is in bounds and matches the target
    result >= 0 ==>
        (0 <= result
         && (result as usize) < nums.len()
         && nums[result as usize] == target)
)]
#[ensures(
    // And all earlier positions j < result do not match target
    result >= 0 ==>
        forall |j: usize| j < (result as usize) ==> nums[j] != target
)]
#[ensures(
    // If we return –1, then no element in the entire vector equals target
    result < 0 ==>
        forall |j: usize| j < nums.len() ==> nums[j] != target
)]
fn linear_search(nums: Vec<i32>, target: i32) -> i32 {
    // Loop invariant: for all j < i, nums[j] != target
    // Decreases measure: nums.len() - i, so the loop terminates
    #[invariant(forall |j: usize| j < i ==> nums[j] != target)]
    #[decreases(nums.len() - i)]
    for (i, &num) in nums.iter().enumerate() {
        if num == target {
            return i as i32;
        }
    }

    -1
}

